#include <print>
#include <vector>

int& max_of(int& x, int& y) {
    if (x > y) return x;
    return y;
}

void reverse(std::vector<int>& v) {
    int t = v[0];
    v[0] = v[3];
    v[3] = t;
    int u = v[1];
    v[1] = v[2];
    v[2] = u;
}

int main() {
    int a = 30, b = 70;
    max_of(a, b) = 0;
    std::println("a={}, b={}", a, b);

    std::vector<int> v = {1, 2, 3, 4};
    reverse(v);
    std::println("{}", v);

    int c = 30, d = 40;
    int* p = &c;
    p = &d;
    *p = 44;
    std::println("c={}, d={}", c, d);
    // 引用是本人的外号，出生那一行就绑死；纸条上记的是号，涂掉重填就行，c 毫发无损
    return 0;
}

